import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";
import { LESSONS } from "../../src/shared/content/index";
import { resetData } from "./reset-data";
import { openTestDatabase, type TestProxy } from "./test-db";

/**
 * Structural invariants of the curriculum graph, asserted on a real database.
 *
 * `docs/CURRICULUM_COVERAGE_MATRIX.md` is generated by
 * `scripts/curriculum-coverage.mjs` from the same seed path, so the numbers in
 * that document are only true while these assertions hold. Without this suite
 * the graph has no durable guard: `POST /api/data/import` writes
 * `INSERT OR IGNORE INTO skill_prerequisites` (`src/worker/routes/data.ts`), so
 * an import can add edges the offline registry validator never looks at.
 *
 * The invariants, and why each one matters:
 *
 *   - Acyclic. A cycle would mean skill A is a prerequisite of B and B of A, so
 *     a learner could never enter either one; the planner would also never
 *     schedule them.
 *   - No dangling edge. A foreign key would reject this at write time; the
 *     assertion exists so a future schema change that drops the FK does not
 *     quietly reintroduce it.
 *   - No cross-subject edge. "Read a fraction, in English" is not a
 *     prerequisite relationship a Grade 4 learner can act on.
 *   - No forward-grade edge. A prerequisite introduced in Grade 5 cannot be
 *     needed before the lesson that introduces it. Grade boundaries are the
 *     only ordering signal the catalogue has, so this is the check that keeps
 *     the sequence teachable.
 *   - Every lesson resolves to an objective. A lesson with a NULL or misspelled
 *     `objective_id` leaves the graph silently, and every coverage number
 *     downstream becomes a lie about a lesson nobody can see.
 *   - Every objective belongs to the subject of its skill, and its grade falls
 *     inside that skill's grade band. These two are what make the mapping
 *     meaningful rather than merely present.
 */

type Edge = { skill_id: string; prerequisite_id: string };

type SkillRow = { id: string; subject_id: string; grade_from: number; grade_to: number };

type ObjectiveRow = {
  id: string;
  subject_id: string;
  grade: number;
  skill_id: string | null;
};

type LessonObjectiveRow = {
  lesson_id: string;
  objective_id: string | null;
  skill_id: string | null;
  subject_id: string;
};

let proxy: TestProxy;
let edges: Edge[];
let skills: Map<string, SkillRow>;
let objectives: ObjectiveRow[];
let lessons: LessonObjectiveRow[];

/** Depth-first search over `edges`, reporting each cycle it finds once. */
export function findCycles(rows: readonly Edge[]): string[][] {
  const outgoing = new Map<string, string[]>();
  for (const edge of rows) {
    const list = outgoing.get(edge.skill_id);
    if (list) list.push(edge.prerequisite_id);
    else outgoing.set(edge.skill_id, [edge.prerequisite_id]);
  }

  const WHITE = 0;
  const GREY = 1;
  const BLACK = 2;
  const colour = new Map<string, number>();
  const cycles: string[][] = [];

  const visit = (node: string, path: string[]): void => {
    colour.set(node, GREY);
    path.push(node);
    for (const next of outgoing.get(node) ?? []) {
      const state = colour.get(next) ?? WHITE;
      if (state === GREY) {
        cycles.push([...path.slice(path.indexOf(next)), next]);
      } else if (state === WHITE) {
        visit(next, path);
      }
    }
    path.pop();
    colour.set(node, BLACK);
  };

  for (const node of outgoing.keys()) {
    if ((colour.get(node) ?? WHITE) === WHITE) visit(node, []);
  }
  return cycles;
}

beforeAll(async () => {
  proxy = await openTestDatabase();
});

afterAll(async () => {
  await proxy.dispose();
});

beforeEach(async () => {
  await resetData(proxy.env.DB);

  const db = proxy.env.DB;
  const edgeRows = await db
    .prepare("SELECT skill_id, prerequisite_id FROM skill_prerequisites")
    .all<Edge>();
  edges = edgeRows.results ?? [];

  const skillRows = await db
    .prepare("SELECT id, subject_id, grade_from, grade_to FROM skills")
    .all<SkillRow>();
  skills = new Map((skillRows.results ?? []).map((row) => [row.id, row]));

  const objectiveRows = await db
    .prepare("SELECT id, subject_id, grade, skill_id FROM curriculum_objectives")
    .all<ObjectiveRow>();
  objectives = objectiveRows.results ?? [];

  const lessonRows = await db
    .prepare(
      `SELECT l.id AS lesson_id,
              lm.objective_id AS objective_id,
              l.skill_id AS skill_id,
              l.subject_id AS subject_id
         FROM lessons l
         LEFT JOIN lesson_metadata lm ON lm.lesson_id = l.id
        ORDER BY l.id`,
    )
    .all<LessonObjectiveRow>();
  lessons = lessonRows.results ?? [];
});

describe("the prerequisite graph is a teachable order", () => {
  it("has no cycles", () => {
    expect(findCycles(edges)).toEqual([]);
  });

  it("has no edge pointing at a skill that does not exist", () => {
    const dangling = edges.filter(
      (edge) => !skills.has(edge.skill_id) || !skills.has(edge.prerequisite_id),
    );
    expect(dangling).toEqual([]);
  });

  it("has no edge across subjects", () => {
    const crossSubject = edges.filter(
      (edge) => skills.get(edge.skill_id)!.subject_id !== skills.get(edge.prerequisite_id)!.subject_id,
    );
    expect(crossSubject.map((edge) => `${edge.skill_id} <- ${edge.prerequisite_id}`)).toEqual([]);
  });

  it("never makes a later-grade skill a prerequisite of an earlier-grade one", () => {
    const forward = edges.filter(
      (edge) =>
        skills.get(edge.prerequisite_id)!.grade_from > skills.get(edge.skill_id)!.grade_from,
    );
    expect(forward.map((edge) => `${edge.skill_id} <- ${edge.prerequisite_id}`)).toEqual([]);
  });

  it("has exactly the measured 33 edges across 5 subjects", () => {
    expect(edges).toHaveLength(33);
    const bySubject = new Map<string, number>();
    for (const edge of edges) {
      const subject = skills.get(edge.skill_id)!.subject_id;
      bySubject.set(subject, (bySubject.get(subject) ?? 0) + 1);
    }
    expect(Object.fromEntries(bySubject)).toEqual({
      math: 7,
      english: 6,
      vietnamese: 6,
      science: 7,
      debate: 7,
    });
  });
});

describe("every lesson is reachable from the curriculum graph", () => {
  it("seeds exactly the 50 registry lessons", () => {
    expect(lessons).toHaveLength(50);
    expect(lessons.map((lesson) => lesson.lesson_id).sort()).toEqual(
      LESSONS.map((lesson) => lesson.id).sort(),
    );
  });

  it("leaves no lesson without an objective", () => {
    const unmapped = lessons.filter((lesson) => lesson.objective_id === null);
    expect(unmapped.map((lesson) => lesson.lesson_id)).toEqual([]);
  });

  it("leaves no lesson pointing at an objective that does not exist", () => {
    const known = new Set(objectives.map((objective) => objective.id));
    const dangling = lessons.filter(
      (lesson) => lesson.objective_id !== null && !known.has(lesson.objective_id),
    );
    expect(dangling.map((lesson) => `${lesson.lesson_id} -> ${lesson.objective_id}`)).toEqual([]);
  });

  it("keeps the registry's declared objectiveId identical to what the seed wrote", () => {
    const stored = new Map(lessons.map((lesson) => [lesson.lesson_id, lesson.objective_id]));
    const disagreements = LESSONS.filter(
      (lesson) => stored.get(lesson.id) !== (lesson.objectiveId ?? null),
    );
    expect(disagreements.map((lesson) => lesson.id)).toEqual([]);
  });

  it("leaves no lesson whose skill is missing from the catalogue", () => {
    const orphans = lessons.filter(
      (lesson) => lesson.skill_id !== null && !skills.has(lesson.skill_id),
    );
    expect(orphans.map((lesson) => `${lesson.lesson_id} -> ${lesson.skill_id}`)).toEqual([]);
  });
});

describe("every objective is a real curriculum target", () => {
  it("attaches each objective to a skill in the same subject", () => {
    const mismatched = objectives.filter((objective) => {
      if (objective.skill_id === null) return false;
      const skill = skills.get(objective.skill_id);
      return skill === undefined || skill.subject_id !== objective.subject_id;
    });
    expect(mismatched.map((objective) => objective.id)).toEqual([]);
  });

  it("never places an objective outside the grade band of its skill", () => {
    const outside = objectives.filter((objective) => {
      if (objective.skill_id === null) return false;
      const skill = skills.get(objective.skill_id);
      if (skill === undefined) return false;
      return objective.grade < skill.grade_from || objective.grade > skill.grade_to;
    });
    expect(outside.map((objective) => objective.id)).toEqual([]);
  });

  it("seeds 40 objectives: 32 national outcomes and 8 supplemental ones", () => {
    expect(objectives).toHaveLength(40);
    const national = objectives.filter((objective) => objective.subject_id !== "debate");
    expect(national, "every non-debate objective cites a GDPT 2018 code").toHaveLength(32);
    expect(objectives.length - national.length).toBe(8);
  });
});

describe("the measured gaps are the documented gaps", () => {
  it("names the one skill with no objective, rather than hiding it", () => {
    const withObjective = new Set(
      objectives.map((objective) => objective.skill_id).filter((id): id is string => id !== null),
    );
    const orphans = [...skills.keys()].filter((id) => !withObjective.has(id)).sort();
    // `math-frac-identify` is a Grade 3–4 foundation skill whose outcome is
    // covered by `obj-math-frac-intro`; it is reported as a gap in
    // `docs/CURRICULUM_COVERAGE_MATRIX.md` rather than given a duplicate
    // objective row it does not have.
    expect(orphans).toEqual(["math-frac-identify"]);
  });

  it("leaves no objective without a lesson", () => {
    const used = new Set(
      lessons.map((lesson) => lesson.objective_id).filter((id): id is string => id !== null),
    );
    const unused = objectives.filter((objective) => !used.has(objective.id));
    expect(unused.map((objective) => objective.id)).toEqual([]);
  });

  it("does not claim the Grade 4–5 programme is complete", () => {
    // The three denominators the audit matrix publishes. Asserting them here
    // keeps the coverage percentages from drifting silently if the seed grows.
    const GRADE_4_5_PERIOD_BUDGET = 1400;
    const COVERAGE = (50 / GRADE_4_5_PERIOD_BUDGET) * 100;
    expect(COVERAGE.toFixed(2)).toBe("3.57");
    expect(lessons.length).toBeLessThan(GRADE_4_5_PERIOD_BUDGET / 10);
  });
});
